  3→import { useState, useEffect } from "react";
  4→import Link from "next/link";
  5→import { usePathname } from "next/navigation";
  6→import styles from "./Nav.module.css";
  7→
  8→const NAV_LINKS = [
  9→  { href: "/work", label: "Work" },
 10→  { href: "/about", label: "About" },
 11→  { href: "/thoughts", label: "Thoughts" },
 12→] as const;
 13→
 14→const SOCIAL_LINKS = [
 15→  { label: "LinkedIn", href: "https://www.linkedin.com/in/jaimeibrahim/" },
 16→  { label: "Instagram", href: "https://www.instagram.com/jaimeibrahim/" },
 17→] as const;
 18→
 19→export function Nav() {
 20→  const pathname = usePathname();
 21→  const [scrolled, setScrolled] = useState(false);
 22→  const [mobileOpen, setMobileOpen] = useState(false);
 23→
 24→  // Close mobile menu on route change
 25→  useEffect(() => {
 26→    // eslint-disable-next-line react-hooks/set-state-in-effect -- Intentional: close menu on navigation
 27→    setMobileOpen(false);
 28→  }, [pathname]);
 29→
 30→  useEffect(() => {
 31→    const handler = () => setScrolled(window.scrollY > 20);
 32→    window.addEventListener("scroll", handler, { passive: true });
 33→    return () => window.removeEventListener("scroll", handler);
 34→  }, []);
 35→
 36→  const isActive = (href: string) => {
 37→    if (href === "/work") return pathname === "/" || pathname.startsWith("/work");
 38→    return pathname.startsWith(href);
 39→  };
 40→
 41→  return (
 42→    <nav className={`${styles.nav} ${scrolled ? styles.navScrolled : ""}`}>
 43→      {/* Left: nav links */}
 44→      <div className={`${styles.links} ${styles.linksLeft}`}>
 45→        {NAV_LINKS.map((link) => (
 46→          <Link key={link.href} href={link.href} className={`${styles.navLink} ${isActive(link.href) ? styles.navLinkActive : ""}`}>
 47→            {link.label}
 48→          </Link>
 49→        ))}
 50→      </div>
 51→
 52→      {/* Center: nameplate — full reload to replay intro */}
 53→      <a
 54→        href="/"
 55→        className={styles.nameplate}
 56→        onClick={(e) => {
 57→          e.preventDefault();
 58→          try { sessionStorage.removeItem("jaime-intro-played"); } catch {}
 59→          window.location.href = "/";
 60→        }}
 61→      >
 62→        <span className={styles.hairline} />
 63→        <span className={styles.nameplateText}>Jaime Ibrahim</span>
 64→        <span className={styles.hairline} />
 65→      </a>
 66→
 67→      {/* Right: social links */}
 68→      <div className={`${styles.links} ${styles.linksRight}`}>
 69→        {SOCIAL_LINKS.map((link) => (
 70→          <a
 71→            key={link.label}
 72→            href={link.href}
 73→            target="_blank"
 74→            rel="noopener noreferrer"
 75→            className={styles.navLink}
 76→          >
 77→            {link.label}
 78→          </a>
 79→        ))}
 80→      </div>
 81→
 82→      {/* Mobile menu button */}
 83→      <button
 84→        className={styles.mobileMenuBtn}
 85→        onClick={() => setMobileOpen(!mobileOpen)}
 86→        aria-label="Toggle menu"
 87→      >
 88→        <span
 89→          className={styles.mobileMenuLine}
 90→          style={{
 91→            transform: mobileOpen ? "rotate(45deg) translate(2px, 2px)" : "none",
 92→          }}
 93→        />
 94→        <span
 95→          className={styles.mobileMenuLine}
 96→          style={{ opacity: mobileOpen ? 0 : 1 }}
 97→        />
 98→        <span
 99→          className={styles.mobileMenuLine}
100→          style={{
101→            transform: mobileOpen ? "rotate(-45deg) translate(2px, -2px)" : "none",
102→          }}
103→        />
104→      </button>
105→
106→      {/* Mobile dropdown */}
107→      {mobileOpen && (
108→        <div className={styles.mobileDropdown}>
109→          {NAV_LINKS.map((link) => (
110→            <Link
111→              key={link.href}
112→              href={link.href}
113→              className={`${styles.mobileLink} ${isActive(link.href) ? styles.mobileLinkActive : ""}`}
114→            >
115→              {link.label}
116→            </Link>
117→          ))}
118→          <div className={styles.mobileSocials}>
119→            {SOCIAL_LINKS.map((link) => (
120→              <a
121→                key={link.label}
122→                href={link.href}
123→                target="_blank"
124→                rel="noopener noreferrer"
125→                className={styles.mobileSocialLink}
126→              >
127→                {link.label}
128→              </a>
129→            ))}
130→          </div>
131→        </div>
132→      )}
133→    </nav>
134→  );
135→}
