19→export function Footer() {
20→  const [hovered, setHovered] = useState(false);
21→  const [weather, setWeather] = useState<{ temp: number; icon: string } | null>(null);
22→
23→  useEffect(() => {
24→    const fetchWeather = () => {
25→      fetch("https://api.open-meteo.com/v1/forecast?latitude=40.7128&longitude=-74.006&current=temperature_2m,weather_code&temperature_unit=fahrenheit")
26→        .then((r) => r.json())
27→        .then((d) => {
28→          if (d.current) {
29→            const temp = Math.round(d.current.temperature_2m);
30→            const code = d.current.weather_code;
31→            let icon = "Clear";
32→            if (code === 0) icon = "Clear";
33→            else if (code <= 3) icon = "Partly cloudy";
34→            else if (code <= 48) icon = "Cloudy";
35→            else if (code <= 67) icon = "Rain";
36→            else if (code <= 77) icon = "Snow";
37→            else if (code <= 82) icon = "Rain";
38→            else if (code <= 86) icon = "Snow";
39→            else icon = "Storm";
40→            setWeather({ temp, icon });
41→          }
42→        })
43→        .catch(() => {});
44→    };
45→    // Defer weather fetch so it doesn't compete with LCP resources
46→    if ("requestIdleCallback" in window) {
47→      const id = requestIdleCallback(fetchWeather);
48→      return () => cancelIdleCallback(id);
49→    } else {
50→      const id = setTimeout(fetchWeather, 2000);
51→      return () => clearTimeout(id);
52→    }
53→  }, []);
54→
55→  return (
56→    <footer style={{ position: "relative", zIndex: 1 }}>
57→      <div
58→        className={styles.ctaBlock}
59→        onMouseEnter={() => setHovered(true)}
60→        onMouseLeave={() => setHovered(false)}
61→      >
62→        <Link href="/about" style={{ display: "block", cursor: "pointer" }}>
63→          <p className={styles.ctaText} style={{ color: hovered ? "var(--muted)" : "var(--text)" }}>
64→            Let&apos;s Work Together
65→          </p>
66→        </Link>
67→        <p className={styles.ctaEmail}>
68→          <a href="https://www.linkedin.com/in/jaimeibrahim/" target="_blank" rel="noopener noreferrer" style={{ color: "inherit" }}>
69→            Connect on LinkedIn
70→          </a>
71→        </p>
72→      </div>
73→
74→      <div className={styles.infoBar}>
75→        <span className={styles.socials}>
76→          <a href="https://www.linkedin.com/in/jaimeibrahim/" target="_blank" rel="noopener noreferrer" className={styles.socialLink} aria-label="LinkedIn">
77→            {LinkedInIcon}
78→          </a>
79→          <a href="https://www.instagram.com/jaimeibrahim/" target="_blank" rel="noopener noreferrer" className={styles.socialLink} aria-label="Instagram">
80→            {InstagramIcon}
81→          </a>
82→        </span>
83→        <span className={styles.copyright}>
84→          &copy; 2026 Jaime Ibrahim &nbsp;&nbsp;|&nbsp;&nbsp; Brand Design Director &nbsp;&nbsp;|&nbsp;&nbsp; New York City
85→          {weather && (
86→            <span style={{ opacity: 0.5, fontSize: 11 }}>
87→              &nbsp;&nbsp;{weather.icon} {weather.temp}&deg;F
88→            </span>
89→          )}
90→        </span>
91→      </div>
92→    </footer>
93→  );
94→}
